<script setup lang="ts">
import { ref, computed, onMounted } from 'vue'
import { api, date, money, type Row } from '../api'
import Panel from './Panel.vue'
type Kind='membership'|'recharge'|'price'|'training'|'coupon'
const tabs: {key:Kind;name:string;path:string;create:string}[]=[
 {key:'membership',name:'会员产品',path:'/memberships/products/manage',create:'/memberships/products'},
 {key:'recharge',name:'充值方案',path:'/memberships/recharge-plans/manage',create:'/memberships/recharge-plans'},
 {key:'price',name:'场地价格',path:'/venues/price-rules/manage',create:'/venues/price-rules'},
 {key:'training',name:'课程产品',path:'/training/products',create:'/training/products'},
 {key:'coupon',name:'联盟券',path:'/alliance/coupon-templates',create:'/alliance/coupon-templates'},
]
const kind=ref<Kind>('membership'), current=computed(()=>tabs.find(t=>t.key===kind.value)!), rows=ref<Row[]>([]), loading=ref(false),error=ref(''),notice=ref(''), search=ref(''),editor=ref(false),selected=ref<Row|null>(null),draft=ref<Row>({}),saving=ref(false),formError=ref(''),slots=ref<Row[]>([]),merchants=ref<Row[]>([]), statusOnly=ref(false)
const filtered=computed(()=>rows.value.filter(r=>`${r.name} ${r.code}`.toLowerCase().includes(search.value.toLowerCase())))
const nowLocal=()=>{const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
const localDate=(s?:string)=>s?new Date(new Date(s).getTime()-new Date(s).getTimezoneOffset()*60000).toISOString().slice(0,16):''
const levels={EXPERIENCE:'体验会员',REGULAR:'普通会员',GOLD:'金卡会员',BLACK:'黑金会员'}
let sequence=0
async function load(){const run=++sequence;loading.value=true;error.value='';rows.value=[];try{const r=await api(current.value.path);if(run===sequence)rows.value=Array.isArray(r)?r:r.items||[]}catch(e){error.value=(e as Error).message}finally{if(run===sequence)loading.value=false}}
function switchTab(k:Kind){kind.value=k;search.value='';notice.value='';load()}
async function edit(row:Row|null=null,onlyStatus=false){selected.value=row;statusOnly.value=onlyStatus;formError.value='';editor.value=true;const r=row||{};draft.value={...r,code:r.code||`PC-${crypto.randomUUID().slice(0,8).toUpperCase()}`,name:r.name||'',level:r.level||'REGULAR',price:((r.priceCents??0)/100).toFixed(2),principal:((r.principalCents??10000)/100).toFixed(2),gift:((r.giftCents??0)/100).toFixed(2),faceValue:((r.faceValueCents??0)/100).toFixed(2),durationDays:r.durationDays||365,validityDays:r.validityDays||90,totalSessions:r.totalSessions||10,audience:r.audience||'ADULT',effectiveFrom:nowLocal(),effectiveTo:'',validFrom:localDate(r.validFrom)||nowLocal(),validTo:localDate(r.validTo),description:r.benefits?.description||'',activityName:r.activityName||'',benefitDescription:r.benefitDescription||'',merchantId:r.merchantId||'',timeSlotId:r.timeSlotId||'',weekdays:[0,1,2,3,4,5,6].filter(day=>((r.weekdayMask??127)&(1<<day))!==0),newcomer:r.newcomerPriceCents===null||r.newcomerPriceCents===undefined?'':(r.newcomerPriceCents/100).toFixed(2),issueLimit:r.issueLimit||100,claimLimitPerUser:r.claimLimitPerUser||1,allowVenueBooking:r.allowVenueBooking||false,enabled:r.enabled??true,reason:'',idempotencyKey:crypto.randomUUID()};try{if(kind.value==='price')slots.value=await api('/venues/time-slots/manage');if(kind.value==='coupon')merchants.value=await api('/alliance/merchants')}catch(e){formError.value=(e as Error).message}}
function cents(value:string){if(!/^\d+(\.\d{1,2})?$/.test(String(value)))throw new Error('金额请填写最多两位小数的非负数字');const result=Math.round(Number(value)*100);if(!Number.isSafeInteger(result))throw new Error('金额超出范围');return result}
async function save(){saving.value=true;formError.value='';try{const d=draft.value,k=kind.value,r=selected.value;let path=current.value.create,method='POST',body:Row={};const audit={reason:d.reason,idempotencyKey:d.idempotencyKey};
 if(statusOnly.value&&r){path+=`/${r.id}`+(k==='training'?'':'/status');method=k==='training'?'PATCH':'POST';body={enabled:d.enabled,...audit,...(k==='coupon'?{allowVenueBooking:d.allowVenueBooking}:{})}}
 else if(k==='membership'||k==='price'||k==='recharge'){
  body={name:d.name,effectiveFrom:new Date(d.effectiveFrom).toISOString(),...(d.effectiveTo?{effectiveTo:new Date(d.effectiveTo).toISOString()}:{}),...audit};
  if(k==='membership')Object.assign(body,{level:d.level,priceCents:cents(d.price),durationDays:Number(d.durationDays),benefits:{...(r?.benefits||{}),description:d.description}})
  if(k==='price'){if(!d.weekdays.length)throw new Error('请至少选择一个适用星期');Object.assign(body,{priceCents:cents(d.price),weekdayMask:d.weekdays.reduce((n:number,day:number)=>n|(1<<day),0),...(d.timeSlotId?{timeSlotId:d.timeSlotId}:{}),...(d.newcomer!==''?{newcomerPriceCents:cents(d.newcomer)}:{})})}
  if(k==='recharge')Object.assign(body,{principalCents:cents(d.principal),giftCents:cents(d.gift)})
  if(r&&k!=='recharge')path+=`/${r.id}/versions`;else body.code=d.code
 }else if(k==='training'){
  body={name:d.name,totalSessions:Number(d.totalSessions),validityDays:Number(d.validityDays),priceCents:cents(d.price),refundRule:r?.refundRule||{mode:'UNCONSUMED_PRO_RATA',...(d.audience==='YOUTH'?{guardianConsentRequired:true}:{})},reason:d.reason};
  if(r){path+=`/${r.id}`;method='PATCH';body.idempotencyKey=d.idempotencyKey}else Object.assign(body,{code:d.code,audience:d.audience,creationIdempotencyKey:d.idempotencyKey})
 }else{
  body={code:d.code,name:d.name,merchantId:d.merchantId,activityName:d.activityName,benefitDescription:d.benefitDescription,faceValueCents:cents(d.faceValue),validFrom:new Date(d.validFrom).toISOString(),validTo:new Date(d.validTo).toISOString(),issueLimit:Number(d.issueLimit),claimLimitPerUser:Number(d.claimLimitPerUser),allowVenueBooking:d.allowVenueBooking}
 }
 await api(path,method,body);notice.value=statusOnly.value?'状态已更新':r?'变更已保存':'已创建，请核对启用状态和生效时间';editor.value=false;await load()
 }catch(e){formError.value=(e as Error).message}finally{saving.value=false}}
const priceOf=(row:Row)=>kind.value==='recharge'?money(row.principalCents):kind.value==='coupon'?money(row.faceValueCents):money(row.priceCents)
onMounted(load)
</script>
<template><section><nav class="tabs" aria-label="业务配置分类"><button v-for="tab in tabs" :key="tab.key" :class="{active:kind===tab.key}" :aria-current="kind===tab.key?'page':undefined" @click="switchTab(tab.key)">{{ tab.name }}</button></nav><div v-if="notice" class="notice" role="status">{{ notice }}</div><div class="toolbar"><label class="grow">查找{{ current.name }}<input v-model="search" placeholder="按名称或编号筛选当前列表"></label><button @click="edit()">新建{{ current.name }}</button><button class="secondary" :disabled="loading" @click="load">刷新</button></div><p class="muted small" v-if="['membership','recharge','price'].includes(kind)">价格和权益按版本生效，历史订单保留成交时的规则。</p><p v-if="error" class="error" role="alert">{{ error }}</p><div class="surface table-wrap" :aria-busy="loading"><table><thead><tr><th>名称 / 编号</th><th>金额</th><th>适用范围</th><th>生效 / 有效时间</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in filtered" :key="row.id"><td><strong>{{ row.name }}</strong><div class="small muted">{{ row.code }}<span v-if="row.version"> · 第 {{ row.version }} 版</span></div></td><td>{{ priceOf(row) }}<div v-if="kind==='recharge'" class="small muted">赠送 {{ money(row.giftCents) }}</div></td><td>{{ kind==='training'?(row.audience==='YOUTH'?'青少年':'成人')+' · '+row.totalSessions+' 次课':kind==='membership'?levels[row.level as keyof typeof levels]+' · '+row.durationDays+' 天':kind==='coupon'?(row.merchant?.name||'联盟商户'):kind==='price'?(row.timeSlot?.label||row.timeSlot?.name||'全部时段'):'会员充值' }}</td><td>{{ date(row.effectiveFrom||row.validFrom) }}<div v-if="row.effectiveTo||row.validTo" class="small muted">至 {{ date(row.effectiveTo||row.validTo) }}</div></td><td><span class="badge" :class="row.enabled?'good':'warn'">{{ row.enabled?'启用':'停用' }}</span></td><td><div class="row-actions"><button v-if="kind!=='coupon'" class="link" @click="edit(row)">{{ kind==='training'?'编辑':'新建版本' }}</button><button class="link" @click="edit(row,true)">启停设置</button></div></td></tr></tbody></table><div v-if="!filtered.length" class="empty">{{ loading?'正在同步配置…':'暂无符合条件的配置' }}</div></div><Panel v-if="editor" :title="statusOnly?'启停设置':(selected?'更新':'新建')+current.name" :busy="saving" @close="editor=false"><form @submit.prevent="save"><p v-if="selected" class="muted">{{ selected.name }} · {{ selected.code }}</p><template v-if="statusOnly"><label class="check"><input v-model="draft.enabled" type="checkbox">启用此配置</label></template><template v-else><label v-if="!selected||kind==='recharge'">业务编号<input v-model="draft.code" required maxlength="40"></label><label>名称<input v-model="draft.name" required minlength="2" maxlength="80"></label><template v-if="kind==='membership'"><label>会员等级<select v-model="draft.level"><option v-for="(name,key) in levels" :value="key">{{ name }}</option></select></label><label>权益说明<textarea v-model="draft.description" maxlength="300"></textarea></label><label>有效天数<input v-model="draft.durationDays" type="number" min="1" max="3650" required></label></template><template v-if="kind==='training'"><label v-if="!selected">培训对象<select v-model="draft.audience"><option value="ADULT">成人</option><option value="YOUTH">青少年</option></select></label><div class="form-grid"><label>课次数<input v-model="draft.totalSessions" type="number" min="1" required></label><label>有效天数<input v-model="draft.validityDays" type="number" min="1" required></label></div><p class="small muted">未消课金额按比例退费；青少年课程遵循当前有效监管规则。</p></template><label v-if="['membership','training','price'].includes(kind)">售价（元）<input v-model="draft.price" inputmode="decimal" required></label><template v-if="kind==='recharge'"><div class="form-grid"><label>充值本金（元）<input v-model="draft.principal" inputmode="decimal" required></label><label>赠送余额（元）<input v-model="draft.gift" inputmode="decimal" required></label></div></template><template v-if="kind==='price'"><label>适用时段<select v-model="draft.timeSlotId"><option value="">全部时段</option><option v-for="slot in slots" :value="slot.id">{{ slot.label||slot.name||`${slot.startTime}–${slot.endTime}` }}</option></select></label><fieldset><legend>适用星期</legend><div class="role-grid"><label v-for="(label,i) in ['日','一','二','三','四','五','六']" class="check"><input type="checkbox" v-model="draft.weekdays" :value="i">周{{ label }}</label></div></fieldset><label>新客价（元，可不填）<input v-model="draft.newcomer" inputmode="decimal"></label></template><template v-if="['membership','recharge','price'].includes(kind)"><label>生效时间<input v-model="draft.effectiveFrom" type="datetime-local" required></label><label>结束时间（可不填）<input v-model="draft.effectiveTo" type="datetime-local"></label></template><template v-if="kind==='coupon'"><label>联盟商户<select v-model="draft.merchantId" required><option value="" disabled>请选择商户</option><option v-for="m in merchants" :value="m.id">{{ m.name }}</option></select></label><label>活动名称<input v-model="draft.activityName" required minlength="2" maxlength="120"></label><label>优惠说明<textarea v-model="draft.benefitDescription" required minlength="2" maxlength="300"></textarea></label><label>面额（元）<input v-model="draft.faceValue" inputmode="decimal" required></label><div class="form-grid"><label>发行上限<input v-model="draft.issueLimit" type="number" min="1" max="100000" required></label><label>每人领取上限<input v-model="draft.claimLimitPerUser" type="number" min="1" max="100" required></label></div><label>有效期开始<input v-model="draft.validFrom" type="datetime-local" required></label><label>有效期结束<input v-model="draft.validTo" type="datetime-local" required></label></template></template><label v-if="kind==='coupon'" class="check"><input v-model="draft.allowVenueBooking" type="checkbox">允许用于场馆订场</label><label v-if="kind!=='coupon'||statusOnly">变更依据<textarea v-model="draft.reason" required minlength="2" maxlength="300" placeholder="记录这次设置的原因"></textarea></label><p v-if="formError" role="alert" class="error">{{ formError }}</p><div class="form-footer"><button :disabled="saving || (statusOnly && !!selected && draft.enabled===selected.enabled && (kind!=='coupon'||draft.allowVenueBooking===selected.allowVenueBooking))">{{ saving?'正在保存…':'确认保存' }}</button><button class="secondary" type="button" :disabled="saving" @click="editor=false">取消</button></div></form></Panel></section></template>
